let rawData = $input.first().json.output;
// $input.first().json.output
rawData = rawData.replace(/```json/g, '').replace(/```/g, '').trim();

const buffer = Buffer.from(rawData, 'utf8');

return [
  {
    json: {
      fileName: "generated_course.ipynb"
    },
    binary: {
      data: {
        data: buffer.toString('base64'),
        mimeType: 'application/x-ipynb+json',
        fileName: 'generated_course.ipynb',
        fileExtension: 'ipynb'
      }
    }
  }
];

const binaryData = $input.item.binary || {};
const keys = Object.keys(binaryData);

// Only remove last file if there are 2+ files (meaning rules file exists)
const materialKeys = keys.length >= 2 ? keys.slice(0, -1) : keys;

const items = [];
for (const key of materialKeys) {
  items.push({
    json: $input.item.json,
    binary: {
      Course_materials: binaryData[key]
    }
  });
}

return items;

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
//Goes through all the files and combines them

const allTexts = $input.all().map(item => item.json.text).join('\n\n---\n\n');

return [{
  json: {
    ...$input.first().json,
    text: allTexts
  }
}];

const input = $input.first().json;
const agentOutput = input.output || input.notebookJson || "";
const attempt = (input.attempt || 0) + 1;

// Clean JSON
let rawJson = agentOutput.trim().replace(/^```(?:json)?\n?/, "").replace(/\n?```$/, "").trim();

// Parse
let notebook;
try {
  notebook = JSON.parse(rawJson);
} catch (e) {
  return [{ json: { valid: false, notebookJson: rawJson, errors: [`Not valid JSON: ${e.message}`], attempt } }];
}

if (!notebook.cells || !Array.isArray(notebook.cells)) {
  return [{ json: { valid: false, notebookJson: rawJson, errors: ["Missing cells array"], attempt } }];
}

// Check only code cells — is the Python runnable?
const errors = [];

for (const [i, cell] of notebook.cells.entries()) {
  if (cell.cell_type !== "code") continue;

  const code = (cell.source || []).join("");

  // Python 2 print (won't run in Python 3)
  if (/print\s+["']/.test(code))
    errors.push(`Cell ${i}: Python 2 print — use print()`);

  // Unfilled placeholders like <YOUR CODE HERE>
  if (/<[A-Z\s]+>/.test(code))
    errors.push(`Cell ${i}: unfilled placeholder`);

  // Unmatched brackets (simplified — catches obvious broken syntax)
  let depth = { p: 0, b: 0, c: 0 };
  for (const ch of code) {
    if (ch === "(") depth.p++; else if (ch === ")") depth.p--;
    if (ch === "[") depth.b++; else if (ch === "]") depth.b--;
    if (ch === "{") depth.c++; else if (ch === "}") depth.c--;
  }
  if (depth.p !== 0) errors.push(`Cell ${i}: unmatched parentheses`);
  if (depth.b !== 0) errors.push(`Cell ${i}: unmatched square brackets`);
  if (depth.c !== 0) errors.push(`Cell ${i}: unmatched curly braces`);
}

// Force pass after 3 attempts to break infinite loop
if (errors.length > 0 && attempt >= 3) {
  return [{ json: { valid: true, notebookJson: JSON.stringify(notebook), errors: [], attempt, forcedPass: true } }];
}

if (errors.length > 0) {
  return [{ json: { valid: false, notebookJson: JSON.stringify(notebook), errors, attempt } }];
}

return [{ json: { valid: true, notebookJson: JSON.stringify(notebook), errors: [], attempt } }];

const binaryData = $input.item.binary;
const rulesFileKey = $input.item.json.rulesFileKey;

if (!rulesFileKey || !binaryData[rulesFileKey]) {
  return [{ json: { ...$input.item.json, text: ' ' } }];
}

return [{
  json: $input.item.json,
  binary: {
    Document_to_follow: binaryData[rulesFileKey]
  }
}];

const binaryData = $input.item.binary || {};
const keys = Object.keys(binaryData);

// Last file is always the rules file
// If only 1 file or no files, no rules exist
if (keys.length < 2) {
  return [{ json: { ...$input.item.json, rulesText: ' ' } }];
}

const lastKey = keys[keys.length - 1];
const lastFile = binaryData[lastKey];

return [{
  json: $input.item.json,
  binary: {
    Document_to_follow: lastFile
  }
}];
